// 1. Strategy Interface
interface TaxStrategy {
    double computeTax(double amount);
}

// 2. Concrete Polymorphic Implementations
class UsTaxStrategy implements TaxStrategy {
    @Override
    public double computeTax(double amount) { return amount * 0.08; }
}

class EuVatStrategy implements TaxStrategy {
    @Override
    public double computeTax(double amount) { return amount * 0.20; }
}

class TaxExemptStrategy implements TaxStrategy {
    @Override
    public double computeTax(double amount) { return 0.0; }
}

// 3. Service Using Injected Strategy (Open-Closed Principle)
class InvoiceProcessor {
    private final TaxStrategy strategy;
    public InvoiceProcessor(TaxStrategy strategy) {
        if (strategy == null) throw new IllegalArgumentException("Strategy cannot be null");
        this.strategy = strategy;
    }
    public double generateTotal(double subtotal) {
        return subtotal + strategy.computeTax(subtotal);
    }
}

public class AfterRefactoringDemo {
    public static void main(String[] args) {
        InvoiceProcessor usInvoice = new InvoiceProcessor(new UsTaxStrategy());
        System.out.println("US Total: $" + usInvoice.generateTotal(100.0));

        InvoiceProcessor euInvoice = new InvoiceProcessor(new EuVatStrategy());
        System.out.println("EU Total: $" + euInvoice.generateTotal(100.0));
    }
}

