interface DiscountRule {
    double applyDiscount(double price);
}

class VipDiscount implements DiscountRule {
    @Override
    public double applyDiscount(double price) {
        return price * 0.80;
    }
}

class RegularDiscount implements DiscountRule {
    @Override
    public double applyDiscount(double price) {
        return price * 0.95;
    }
}

class CheckoutEngine {
    private DiscountRule rule;
    public CheckoutEngine(DiscountRule rule) { this.rule = rule; }
    public double calculate(double price) { return rule.applyDiscount(price); }
}

public class Practice1 {
    public static void main(String[] args) {
        CheckoutEngine vip = new CheckoutEngine(new VipDiscount());
        CheckoutEngine regular = new CheckoutEngine(new RegularDiscount());
        System.out.println("VIP: $" + vip.calculate(100.0));
        System.out.println("Regular: $" + regular.calculate(100.0));
    }
}

interface MessageChannel {
    void deliver(String recipient, String message);
}

class SmsChannel implements MessageChannel {
    @Override
    public void deliver(String recipient, String message) {
        System.out.println("SMS to " + recipient + ": " + message);
    }
}

class EmailChannel implements MessageChannel {
    @Override
    public void deliver(String recipient, String message) {
        System.out.println("Email to " + recipient + ": " + message);
    }
}

class AlertDispatcher {
    private final MessageChannel channel;
    public AlertDispatcher(MessageChannel channel) {
        this.channel = channel;
    }
    public void dispatchAlert(String user, String alert) {
        channel.deliver(user, alert);
    }
}

public class InversionDemo {
    public static void main(String[] args) {
        AlertDispatcher smsAlert = new AlertDispatcher(new SmsChannel());
        smsAlert.dispatchAlert("555-1234", "Server High CPU");

        AlertDispatcher emailAlert = new AlertDispatcher(new EmailChannel());
        emailAlert.dispatchAlert("ops@cloud.com", "Database Failover");
    }
}

class UserSession {
    private final String username;
    private final String role;
    public UserSession(String username, String role) {
        this.username = username;
        this.role = role;
    }
    public String getUsername() { return username; }
    public String getRole() { return role; }
}

interface AccessGuard {
    boolean canExecute(UserSession session, String operation);
}

class RoleAccessGuard implements AccessGuard {
    @Override
    public boolean canExecute(UserSession session, String operation) {
        return "ADMIN".equalsIgnoreCase(session.getRole());
    }
}

public class SessionRefactorDemo {
    public static void main(String[] args) {
        AccessGuard guard = new RoleAccessGuard();
        UserSession admin = new UserSession("keert", "ADMIN");
        UserSession guest = new UserSession("visitor", "GUEST");

        System.out.println("Admin allowed: " + guard.canExecute(admin, "DELETE_DB"));
        System.out.println("Guest allowed: " + guard.canExecute(guest, "DELETE_DB"));
    }
}

