import java.util.HashMap;
import java.util.Map;
import java.util.NoSuchElementException;

class GradeBook {
    private Map<String, Integer> grades = new HashMap<>();
    public void addGrade(String name, int score) { grades.put(name, score); }

    public int findScore(String name) {
        if (!grades.containsKey(name)) {
            throw new NoSuchElementException("Student not found: " + name);
        }
        return grades.get(name);
    }
}

public class SentinelBugDemo {
    public static void main(String[] args) {
        GradeBook book = new GradeBook();
        book.addGrade("Bob", 90);

        try {
            book.findScore("Alice");
        } catch (NoSuchElementException e) {
            System.out.println("Caught: " + e.getMessage());
        }
    }
}

interface FeePolicy {
    double calculateFee(double transactionAmount);
}

class FlatFeePolicy implements FeePolicy {
    private final double flatFee;
    public FlatFeePolicy(double flatFee) {
        this.flatFee = flatFee;
    }
    @Override
    public double calculateFee(double transactionAmount) {
        return flatFee;
    }
}

class TieredFeePolicy implements FeePolicy {
    @Override
    public double calculateFee(double transactionAmount) {
        if (transactionAmount > 1000.0) {
            return transactionAmount * 0.01;
        }
        return transactionAmount * 0.02;
    }
}

class PaymentTransaction {
    private final String id;
    private final double amount;
    public PaymentTransaction(String id, double amount) {
        if (id == null || amount <= 0) {
            throw new IllegalArgumentException("Invalid transaction args");
        }
        this.id = id;
        this.amount = amount;
    }
    public String getId() { return id; }
    public double getAmount() { return amount; }
}

class PaymentSettler {
    private final FeePolicy feePolicy;
    public PaymentSettler(FeePolicy feePolicy) {
        if (feePolicy == null) throw new IllegalArgumentException("Null policy");
        this.feePolicy = feePolicy;
    }
    public double computeNetPayout(PaymentTransaction tx) {
        return tx.getAmount() - feePolicy.calculateFee(tx.getAmount());
    }
}

public class PaymentRefactorEngineApp {
    public static void main(String[] args) {
        PaymentTransaction tx = new PaymentTransaction("TX-101", 2000.0);

        PaymentSettler flatSettler = new PaymentSettler(new FlatFeePolicy(15.0));
        System.out.println("Flat Net: $" + flatSettler.computeNetPayout(tx));

        PaymentSettler tieredSettler = new PaymentSettler(new TieredFeePolicy());
        System.out.println("Tiered Net: $" + tieredSettler.computeNetPayout(tx));
    }
}
